SELECT DISTINCT mol.chembl_id, cr.compound_name, cs.canonical_smiles FROM molecule_dictionary mol JOIN compound_records cr ON mol.molregno = cr.molregno JOIN compound_structures cs ON mol.molregno = cs.molregno JOIN docs d ON cr.doc_id = d.doc_id WHERE d.chembl_id = 'CHEMBL1126796' AND cs.canonical_smiles IS NOT NULL ORDER BY mol.chembl_id ASC, cr.compound_name ASC, cs.canonical_smiles ASC
